package com.codepilot1c.core.edt.development;
import java.util.*;
import java.nio.file.*;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import com.google.gson.*;

/** Durable named fixtures. Individual ledger/native commands remain usable at every step. */
public final class TestDataSetService {
    private static final Gson JSON=new Gson();private static final Object LOCK=new Object();
    private final Path root;private final TestDataLedger ledger;private final TestDataCreateService.Backend backend;
    public TestDataSetService(Path root,TestDataLedger ledger,TestDataCreateService.Backend backend)throws Exception{this.root=root.toAbsolutePath().normalize();this.ledger=ledger;this.backend=backend;Files.createDirectories(this.root);}
    @FunctionalInterface interface Task{JsonObject run()throws Exception;}
    private JsonObject locked(Task task)throws Exception{synchronized(LOCK){try(var channel=FileChannel.open(root.resolve(".lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);var lock=channel.lock()){return task.run();}}}
    public JsonObject prepare(String run,TestDataLedger.Target target,String key,String host,List<Map<String,Object>> items,boolean automatic)throws Exception{
        JsonArray plan=normalize(items);if(key==null||key.isBlank()||key.length()>200)throw new IllegalArgumentException("Valid idempotency_key required");
        String id="set-"+sha(JSON.toJson(List.of(run,key))),fingerprint=sha(JSON.toJson(List.of(host,plan,automatic)));
        return locked(()->{Path file=file(id);JsonObject doc;if(Files.exists(file)){doc=read(id,run,target);if(!fingerprint.equals(doc.get("fingerprint").getAsString()))throw new IllegalArgumentException("Set key already used with different arguments");return view(doc);}
            if(!target.equals(backend.target(host,true)))throw new IllegalArgumentException("Host belongs to another base/project");
            JsonObject current=ledger.list(run,target,0,1);if(!"open".equals(current.get("state").getAsString()))throw new IllegalStateException("Ledger is closed");
            doc=new JsonObject();doc.addProperty("set_id",id);doc.addProperty("data_run_id",run);doc.addProperty("project",target.project());doc.addProperty("base_uuid",target.baseUuid());doc.addProperty("host_id",host);doc.addProperty("fingerprint",fingerprint);doc.addProperty("automatic",automatic);doc.addProperty("paused",false);doc.addProperty("phase","create");doc.addProperty("state","ready");doc.add("items",plan);doc.add("created",new JsonObject());doc.add("operations",new JsonObject());doc.add("cleanup",new JsonObject());write(doc);return automatic?step(doc,target,true):view(doc);
        });
    }
    public JsonObject status(String id,String run,TestDataLedger.Target target)throws Exception{return locked(()->{JsonObject doc=read(id,run,target);return step(doc,target,automatic(doc));});}
    public JsonObject pause(String id,String run,TestDataLedger.Target target,boolean paused)throws Exception{return locked(()->{JsonObject doc=read(id,run,target);doc.addProperty("paused",paused);write(doc);return view(doc);});}
    private static boolean automatic(JsonObject doc){return doc.get("automatic").getAsBoolean() && (!doc.has("paused") || !doc.get("paused").getAsBoolean());}
    public JsonObject advance(String id,String run,TestDataLedger.Target target)throws Exception{return locked(()->step(read(id,run,target),target,true));}
    public JsonObject preview(String id,String run,TestDataLedger.Target target)throws Exception{return locked(()->{JsonObject doc=read(id,run,target);if(doc.get("phase").getAsString().equals("create"))step(doc,target,false);JsonObject out=view(doc);out.addProperty("plan_sha256",cleanupHash(doc,target));out.addProperty("writes_database",false);out.add("cleanup_order",cleanupOrder(doc));return out;});}
    public JsonObject cleanup(String id,String run,TestDataLedger.Target target,String expectedPlan)throws Exception{return locked(()->{JsonObject doc=read(id,run,target);if(doc.get("phase").getAsString().equals("cleanup"))return step(doc,target,automatic(doc));step(doc,target,false);JsonObject current=ledger.list(run,target,0,1);if(current.get("pending_creations").getAsInt()>0 || current.get("pending_cleanups").getAsInt()>0)throw new IllegalStateException("Resolve current operation before set cleanup");if(!cleanupHash(doc,target).equals(expectedPlan))throw new IllegalStateException("Stale set cleanup plan");doc.addProperty("phase","cleanup");doc.addProperty("state","ready");write(doc);return automatic(doc)?step(doc,target,true):view(doc);});}
    /** One explicitly requested cleanup step with a fresh task plan; never auto-creates a node. */
    public JsonObject cleanupTaskStep(String id,String run,TestDataLedger.Target target,String expected)throws Exception {
        return locked(()->{
            JsonObject doc=read(id,run,target);if(!cleanupHash(doc,target).equals(expected))throw new IllegalStateException("Stale set cleanup plan");
            JsonObject current=ledger.list(run,target,0,1);
            if(doc.get("phase").getAsString().equals("create")) {
                if(current.get("pending_creations").getAsInt()>0 || current.get("pending_cleanups").getAsInt()>0)throw new IllegalStateException("Resolve pending creation before cleanup");
                doc.addProperty("phase","cleanup");doc.addProperty("state","ready");
            }
            doc.addProperty("paused",true);write(doc);return step(doc,target,true);
        });
    }
    private JsonObject step(JsonObject doc,TestDataLedger.Target target,boolean dispatch)throws Exception{
        String state=doc.get("state").getAsString();if(Set.of("completed","completed_with_skips").contains(state))return view(doc);String run=doc.get("data_run_id").getAsString(),host=doc.get("host_id").getAsString();
        if(doc.get("phase").getAsString().equals("create")){
            if(state.equals("failed"))return view(doc);
            for(JsonElement e:doc.getAsJsonArray("items")){
                JsonObject node=e.getAsJsonObject();String alias=node.get("alias").getAsString();if(doc.getAsJsonObject("created").has(alias))continue;
                JsonObject op=doc.getAsJsonObject("operations").has(alias)?doc.getAsJsonObject("operations").getAsJsonObject(alias):null;
                if(op==null && !dispatch){JsonObject saved=ledger.existingCreation(run,target,"create-"+sha(doc.get("set_id").getAsString()+":"+alias));if(saved!=null){op=new JsonObject();op.addProperty("creation_id",saved.get("creation_id").getAsString());}}
                if(op!=null){op=new TestDataCreateService(ledger,backend).status(run,target,op.get("creation_id").getAsString());}
                else if(dispatch){Map<String,Object> fields=TestDataCreatePlan.fieldValues(node.getAsJsonObject("fields"));for(var field:new ArrayList<>(fields.entrySet()))if(field.getValue() instanceof Map<?,?> ref&&ref.containsKey("ref")){String source=String.valueOf(ref.get("ref"));if(!doc.getAsJsonObject("created").has(source))throw new IllegalStateException("Dependency has not completed");JsonObject owned=doc.getAsJsonObject("created").getAsJsonObject(source);fields.put(field.getKey(),Map.of("type","reference","metadata_fqn",owned.get("metadata_fqn").getAsString(),"uuid",owned.get("uuid").getAsString(),"expected_version",owned.get("expected_version").getAsString()));}long revision=ledger.list(run,target,0,1).get("revision").getAsLong();op=new TestDataCreateService(ledger,backend).createLinked(run,target,revision,doc.get("set_id").getAsString()+":"+alias,host,node.get("metadata_fqn").getAsString(),fields);}
                if(op==null)return view(doc);doc.getAsJsonObject("operations").add(alias,op);String outcome=op.get("state").getAsString();if(op.get("confirmed").getAsBoolean()){doc.getAsJsonObject("created").add(alias,op.getAsJsonObject("record").deepCopy());doc.addProperty("state",doc.getAsJsonObject("created").size()==doc.getAsJsonArray("items").size()?"completed":"ready");}else doc.addProperty("state",Set.of("failed","outcome_unknown").contains(outcome)?outcome:"running");write(doc);return view(doc);
            }
        }else{
            Set<String> blocked=new HashSet<>();for(var done:doc.getAsJsonObject("cleanup").entrySet()){JsonObject op=done.getValue().getAsJsonObject();if(!op.has("marked_for_deletion") || !op.get("marked_for_deletion").getAsBoolean()){if(op.has("state")&&Set.of("skipped","failed").contains(op.get("state").getAsString()))ancestors(doc,done.getKey(),blocked);}}
            for(JsonElement name:cleanupOrder(doc)){
                String alias=name.getAsString();JsonObject old=doc.getAsJsonObject("cleanup").has(alias)?doc.getAsJsonObject("cleanup").getAsJsonObject(alias):null;
                if(old==null){JsonObject external=ledger.cleanupForRecord(run,target,doc.getAsJsonObject("created").getAsJsonObject(alias).get("record_id").getAsString());if(external!=null){old=new TestDataCleanupService(ledger,backend).status(run,target,external.get("cleanup_id").getAsString());doc.getAsJsonObject("cleanup").add(alias,old);write(doc);}}
                if(old!=null&&Set.of("skipped","failed").contains(old.get("state").getAsString()))ancestors(doc,alias,blocked);
                if(old!=null&&old.get("state").getAsString().equals("outcome_unknown")){doc.addProperty("state","outcome_unknown");write(doc);return view(doc);}
                if(old!=null&&Set.of("completed","skipped","failed").contains(old.get("state").getAsString()))continue;
                JsonObject op;
                if(blocked.contains(alias)){op=new JsonObject();op.addProperty("state","skipped");op.addProperty("outcome","dependent_retained");op.addProperty("marked_for_deletion",false);}
                else if(old!=null)op=new TestDataCleanupService(ledger,backend).status(run,target,old.get("cleanup_id").getAsString());
                else if(dispatch){String plan=ledger.preview(run,target,0,1).get("plan_sha256").getAsString();op=new TestDataCleanupService(ledger,backend).start(run,target,doc.get("set_id").getAsString()+":cleanup:"+alias,host,doc.getAsJsonObject("created").getAsJsonObject(alias).get("record_id").getAsString(),plan);}
                else return view(doc);
                doc.getAsJsonObject("cleanup").add(alias,op);doc.addProperty("state",op.get("state").getAsString().equals("outcome_unknown")?"outcome_unknown":op.get("terminal")!=null&&!op.get("terminal").getAsBoolean()?"running":"ready");write(doc);return view(doc);
            }
            boolean skipped=false;for(var e:doc.getAsJsonObject("cleanup").entrySet())if(!e.getValue().getAsJsonObject().get("state").getAsString().equals("completed"))skipped=true;doc.addProperty("state",skipped?"completed_with_skips":"completed");write(doc);
        }
        return view(doc);
    }
    private static void ancestors(JsonObject doc,String alias,Set<String> result){for(JsonElement e:doc.getAsJsonArray("items")){JsonObject node=e.getAsJsonObject();if(!alias.equals(node.get("alias").getAsString()))continue;for(JsonElement field:node.getAsJsonObject("fields").asMap().values())if(field.isJsonObject()&&field.getAsJsonObject().has("ref")){String parent=field.getAsJsonObject().get("ref").getAsString();if(result.add(parent))ancestors(doc,parent,result);}}}
    private static JsonArray cleanupOrder(JsonObject doc){JsonArray order=new JsonArray();JsonArray items=doc.getAsJsonArray("items");for(int i=items.size()-1;i>=0;i--){String alias=items.get(i).getAsJsonObject().get("alias").getAsString();if(doc.getAsJsonObject("created").has(alias))order.add(alias);}return order;}
    private String cleanupHash(JsonObject doc,TestDataLedger.Target target)throws Exception{return sha(JSON.toJson(doc)+ledger.preview(doc.get("data_run_id").getAsString(),target,0,1).get("plan_sha256").getAsString());}
    private JsonObject view(JsonObject doc){JsonObject out=new JsonObject();for(String key:List.of("set_id","data_run_id","project","host_id","automatic","phase","state"))out.add(key,doc.get(key).deepCopy());String state=doc.get("state").getAsString();out.addProperty("paused",doc.has("paused") && doc.get("paused").getAsBoolean());out.addProperty("terminal",Set.of("completed","completed_with_skips","failed","outcome_unknown").contains(state));out.addProperty("total",doc.getAsJsonArray("items").size());out.addProperty("created_count",doc.getAsJsonObject("created").size());out.add("aliases",doc.get("created").deepCopy());JsonObject cleanup=new JsonObject();for(var entry:doc.getAsJsonObject("cleanup").entrySet()){JsonObject value=new JsonObject();for(String key:List.of("state","outcome","cleanup_id","marked_for_deletion"))if(entry.getValue().getAsJsonObject().has(key))value.add(key,entry.getValue().getAsJsonObject().get(key).deepCopy());cleanup.add(entry.getKey(),value);}out.add("cleanup",cleanup);for(JsonElement e:doc.getAsJsonArray("items")){String alias=e.getAsJsonObject().get("alias").getAsString();if(!doc.getAsJsonObject("created").has(alias)){out.addProperty("next_alias",alias);if(doc.getAsJsonObject("operations").has(alias)){JsonObject op=doc.getAsJsonObject("operations").getAsJsonObject(alias);for(String key:List.of("creation_id","request_id","reason"))if(op.has(key))out.add(key,op.get(key).deepCopy());}break;}}out.addProperty("physical_delete_performed",false);out.addProperty("next_tool","edt_test_data");out.addProperty("next_action",automatic(doc)?"set_status":"advance_set");return out;}
    static JsonArray normalize(List<Map<String,Object>> items){if(items==null||items.isEmpty()||items.size()>20)throw new IllegalArgumentException("Provide 1..20 named items");Map<String,JsonObject> nodes=new LinkedHashMap<>();for(Map<String,Object> item:items){if(!item.keySet().equals(Set.of("alias","metadata_fqn","fields")) || !(item.get("alias") instanceof String alias) || !alias.matches("[A-Za-z][A-Za-z0-9_]{0,63}") || nodes.containsKey(alias) || !(item.get("metadata_fqn") instanceof String fqn) || !(item.get("fields") instanceof Map<?,?> raw))throw new IllegalArgumentException("Invalid/duplicate named item");Map<String,Object> simple=new TreeMap<>();Map<String,String> refs=new TreeMap<>();for(var f:raw.entrySet()){if(!(f.getKey() instanceof String name))throw new IllegalArgumentException("Invalid field name");Object value=f.getValue();if(value instanceof Map<?,?> ref&&ref.keySet().equals(Set.of("ref"))&&ref.get("ref") instanceof String source){refs.put(name,source);simple.put(name,"");}else simple.put(name,value);}JsonObject spec=TestDataCreatePlan.normalize(fqn,simple);for(var ref:refs.entrySet()){JsonObject value=new JsonObject();value.addProperty("ref",ref.getValue());spec.getAsJsonObject("fields").add(ref.getKey(),value);}spec.addProperty("alias",alias);nodes.put(alias,spec);}JsonArray out=new JsonArray();Set<String> visiting=new HashSet<>(),done=new HashSet<>();for(String alias:nodes.keySet())visit(alias,nodes,visiting,done,out);if(JSON.toJson(out).getBytes(StandardCharsets.UTF_8).length>64*1024)throw new IllegalArgumentException("Set exceeds 64 KiB");return out;}
    private static void visit(String alias,Map<String,JsonObject> nodes,Set<String> visiting,Set<String> done,JsonArray out){if(done.contains(alias))return;if(!nodes.containsKey(alias))throw new IllegalArgumentException("Unknown alias: "+alias);if(!visiting.add(alias))throw new IllegalArgumentException("Cyclic fixture references");JsonObject node=nodes.get(alias);for(JsonElement value:node.getAsJsonObject("fields").asMap().values())if(value.isJsonObject()&&value.getAsJsonObject().has("ref"))visit(value.getAsJsonObject().get("ref").getAsString(),nodes,visiting,done,out);visiting.remove(alias);done.add(alias);out.add(node);}
    private Path file(String id){if(id==null||!id.matches("set-[a-f0-9]{64}"))throw new IllegalArgumentException("Invalid set_id");return root.resolve(id+".json");}
    private JsonObject read(String id,String run,TestDataLedger.Target target)throws Exception{Path p=file(id);if(Files.isSymbolicLink(p)||Files.size(p)>2*1024*1024)throw new IllegalArgumentException("Invalid fixture manifest");JsonObject doc=JsonParser.parseString(Files.readString(p)).getAsJsonObject();if(!id.equals(doc.get("set_id").getAsString())||!run.equals(doc.get("data_run_id").getAsString())||!target.project().equals(doc.get("project").getAsString())||!target.baseUuid().equals(doc.get("base_uuid").getAsString()))throw new IllegalArgumentException("Set belongs to another ledger/project/base");
        List<Map<String,Object>> items=new ArrayList<>();for(JsonElement e:doc.getAsJsonArray("items")){JsonObject node=e.getAsJsonObject();items.add(Map.of("alias",node.get("alias").getAsString(),"metadata_fqn",node.get("metadata_fqn").getAsString(),"fields",TestDataCreatePlan.fieldValues(node.getAsJsonObject("fields"))));}
        JsonArray normalized=normalize(items);if(!normalized.equals(doc.get("items")) || !sha(JSON.toJson(List.of(doc.get("host_id").getAsString(),normalized,doc.get("automatic").getAsBoolean()))).equals(doc.get("fingerprint").getAsString()))throw new IllegalArgumentException("Fixture plan was modified");
        Set<String> names=new HashSet<>();for(JsonElement e:normalized)names.add(e.getAsJsonObject().get("alias").getAsString());
        for(var entry:doc.getAsJsonObject("operations").entrySet()){
            if(!names.contains(entry.getKey()))throw new IllegalArgumentException("Unknown operation alias");String expected="create-"+sha(id+":"+entry.getKey());if(!expected.equals(entry.getValue().getAsJsonObject().get("creation_id").getAsString()))throw new IllegalArgumentException("Fixture operation provenance mismatch");
        }
        for(var entry:doc.getAsJsonObject("created").entrySet()){
            if(!names.contains(entry.getKey()))throw new IllegalArgumentException("Unknown created alias");JsonObject original=ledger.creation(run,target,"create-"+sha(id+":"+entry.getKey()));if(!"completed".equals(original.get("state").getAsString()) || !entry.getValue().equals(original.get("record")))throw new IllegalArgumentException("Fixture alias has no matching confirmed creation");
        }
        // Recover confirmed per-node primitives even if their aggregate acknowledgement was lost.
        for(String alias:names){JsonObject saved=ledger.existingCreation(run,target,"create-"+sha(id+":"+alias));if(saved!=null&&"completed".equals(saved.get("state").getAsString())&&!doc.getAsJsonObject("created").has(alias))doc.getAsJsonObject("created").add(alias,saved.get("record").deepCopy());}
        Set<String> synthetic=new HashSet<>(),retainedAncestors=new HashSet<>();
        for(var entry:doc.getAsJsonObject("cleanup").entrySet()){
            String alias=entry.getKey();if(!doc.getAsJsonObject("created").has(alias))throw new IllegalArgumentException("Unknown cleanup alias");JsonObject op=entry.getValue().getAsJsonObject();
            if(op.has("cleanup_id")){JsonObject actual=ledger.cleanup(run,target,op.get("cleanup_id").getAsString());if(!actual.get("record_id").equals(doc.getAsJsonObject("created").getAsJsonObject(alias).get("record_id")))throw new IllegalArgumentException("Cleanup record provenance mismatch");JsonObject verified=ledger.cleanupView(run,target,actual.get("cleanup_id").getAsString());entry.setValue(verified);if(Set.of("skipped","failed").contains(verified.get("state").getAsString()))ancestors(doc,alias,retainedAncestors);}
            else if(op.keySet().equals(Set.of("state","outcome","marked_for_deletion"))&&"skipped".equals(op.get("state").getAsString())&&"dependent_retained".equals(op.get("outcome").getAsString())&&!op.get("marked_for_deletion").getAsBoolean())synthetic.add(alias);
            else throw new IllegalArgumentException("Cleanup cache has no authoritative receipt");
        }
        if(!retainedAncestors.containsAll(synthetic))throw new IllegalArgumentException("Retained parent has no verified retained descendant");
        String phase=doc.get("phase").getAsString(),state=doc.get("state").getAsString();if(!Set.of("create","cleanup").contains(phase)||!Set.of("ready","running","completed","completed_with_skips","failed","outcome_unknown").contains(state))throw new IllegalArgumentException("Invalid set phase/state");
        if(phase.equals("create")){if(state.equals("completed")&&doc.getAsJsonObject("created").size()!=normalized.size())throw new IllegalArgumentException("Set completion has no confirmed records");if(doc.getAsJsonObject("created").size()==normalized.size())doc.addProperty("state","completed");}
        else if(Set.of("completed","completed_with_skips").contains(state)){boolean skip=false;if(doc.getAsJsonObject("cleanup").size()!=doc.getAsJsonObject("created").size())throw new IllegalArgumentException("Set cleanup completion is incomplete");for(var e:doc.getAsJsonObject("cleanup").entrySet()){String current=e.getValue().getAsJsonObject().get("state").getAsString();if(!Set.of("completed","skipped","failed").contains(current))throw new IllegalArgumentException("Set cleanup still pending");if(!current.equals("completed"))skip=true;}if(skip!=state.equals("completed_with_skips"))throw new IllegalArgumentException("Set cleanup completion state mismatch");}
        return doc;}
    private void write(JsonObject doc)throws Exception{String json=JSON.toJson(doc);if(json.getBytes(StandardCharsets.UTF_8).length>2*1024*1024)throw new IllegalArgumentException("Set manifest exceeds 2 MiB");Path p=file(doc.get("set_id").getAsString());if(Files.isSymbolicLink(p))throw new IllegalArgumentException("Refusing fixture symlink");Path temp=Files.createTempFile(root,"set-",".tmp");try{Files.writeString(temp,json,StandardCharsets.UTF_8);Files.move(temp,p,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(temp);}}
    private static String sha(String text)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}
}
